{
  "description": "A single quadrupedal creature is shown in right-facing profile against a plain light background, standing on a faintly shaded ground. The animal has the overall body shape, fur, head and limbs of a brown bear, but its dorsal surface, neck, head-top and outer limb joints are covered by a glossy, dark brown to black, segmented exoskeleton resembling that of a beetle. The fur is long, shaggy and medium to dark brown, lighter on the muzzle and darker on the lower legs, covering the head, throat, chest, belly, and all four limbs. The exoskeleton is highly reflective, divided into overlapping transverse plates over the back, with smaller stacked plates around the neck, a helmet-like plate over the forehead and crown, and large smooth cap-like plates over the shoulders and hips. A single long, curved, glossy black horn rises from the forehead plate. The creature stands on four thick furry legs ending in clawed paws, with no wings visible.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with dense brown fur, a lighter tan muzzle, a large black nose, small dark eyes, and fine whiskers; the top and sides are partially covered by a glossy dark helmet-like plate",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "one long, glossy black, sharply pointed horn curving upward and backward, with two small thorn-like notches on its inner concave edge, arising from the forehead plate",
      "where": "on the midline of the forehead, extending dorsally and posteriorly above the head"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with slightly lighter interior fur",
      "where": "on top of the head behind the horn base, protruding above the neck plates"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar, heavily furred legs covered in long shaggy dark brown fur",
      "where": "under the body, two forelegs under the chest/shoulder region and two hind legs under the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with dark pads and five visible light tan to brown curved claws on each paw",
      "where": "at the distal ends of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very small, dark, segmented, pointed tip protruding horizontally from under the rear edge of the dorsal shell",
      "where": "at the extreme posterior left end of the body, just above the hindquarter fur"
    },
    {
      "part": "shell",
      "looks_like": "a large, glossy dark brown-black segmented dorsal exoskeleton made of overlapping transverse plates with thin gold-brown seams, highly reflective, covering the back from neck to rear",
      "where": "over the entire dorsal midline and sides of the torso, from behind the neck plates to the rear"
    },
    {
      "part": "plates",
      "looks_like": "separate large glossy dark plates of the same material as the shell: a helmet over the head, 2-3 stacked collar rings around the neck, a large shoulder cap over each foreleg joint, and a large hip cap over each hind leg joint, plus smaller plates on the throat and chest",
      "where": "on the head, encircling the neck and throat, and capping the outer shoulder and hip joints"
    },
    {
      "part": "markings",
      "looks_like": "a row of eight small oval openings with light tan rims, resembling spiracles, set in a line along the lower edge of the main dorsal shell",
      "where": "along the ventrolateral margin of the main shell, above the furry flank"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
